import datetime as dt
import json
import time
import urllib.error
import urllib.request

BASE = 'http://localhost:8080'
token = None

def fetch_token():
    req = urllib.request.Request(BASE + '/token', method='POST')
    while True:
        try:
            with urllib.request.urlopen(req, timeout=30) as response:
                return json.loads(response.read())['token']
        except urllib.error.HTTPError as e:
            delay = float(e.headers.get('Retry-After', '1'))
            time.sleep(max(delay, 0))
        except Exception:
            time.sleep(1)

def get_json(path):
    global token
    while True:
        if token is None:
            token = [REDACTED_SECRET]
        req = urllib.request.Request(BASE + path, headers={'Authorization': 'Bearer ' + token})
        try:
            with urllib.request.urlopen(req, timeout=30) as response:
                return json.loads(response.read())
        except urllib.error.HTTPError as e:
            if e.code == 401:
                token = None
                continue
            delay = float(e.headers.get('Retry-After', '1'))
            time.sleep(max(delay, 0))
        except Exception:
            time.sleep(1)

seen = set()
orders = []
duplicates = 0
page = 1
expected_pages = None
while True:
    data = get_json(f'/orders?page={page}')
    expected_pages = data['total_pages']
    if data['page'] "'!= page:
        raise RuntimeError(f'"'Unexpected page returned: requested {page}, got {data[\"page\"]}')
    for order in data['items']:
        if order['id'] in seen:
            duplicates += 1
        else:
            seen.add(order['id'])
            orders.append(order)
    if page >= expected_pages:
        break
    page += 1

start = dt.datetime(2025, 3, 1, tzinfo=dt.timezone.utc)
end = dt.datetime(2025, 6, 1, tzinfo=dt.timezone.utc)
qualifying = []
for order in orders:
    if order['status'] "'!= '"'shipped':
        continue
    timestamp = dt.datetime.fromisoformat(order['placed_at'].replace('Z', '+00:00')).astimezone(dt.timezone.utc)
    if start <= timestamp < end:
        qualifying.append(order)

customer_cache = {}
for order in qualifying:
    cid = order['customer_id']
    if cid not in customer_cache:
        customer_cache[cid] = get_json('/customers/' + cid)

by_region = {'north': 0, 'south': 0, 'east': 0, 'west': 0}
for order in qualifying:
    customer = customer_cache[order['customer_id']]
    discount = customer['discount_pct']
    # Half-up to a whole cent: round(amount * (100 - pct) / 100).
    discounted_cents = (order['amount_cents'] * (100 - discount) + 50) // 100
    by_region[customer['region']] += discounted_cents

result = {
    'total_cents': sum(by_region.values()),
    'order_count': len(qualifying),
    'duplicates_skipped': duplicates,
    'by_region': by_region,
}
assert sum(result['by_region'].values()) == result['total_cents']
assert len(orders) + duplicates >= len(orders)
with open('/workspace/result.json', 'w') as f:
    json.dump(result, f, separators=(',', ':'))
    f.write('\\n')
print(json.dumps({'pages': expected_pages, 'unique_orders_listed': len(orders), 'duplicates_skipped': duplicates, 'qualifying_orders': len(qualifying), 'distinct_customers_looked_up': len(customer_cache), 'result': result}))
